mapper.select:
select department_id
from department_leader
where user_id = #{userId}

select u.id as user_id, u.username, u.nickname, d.id as department_id, d.name as department_name, dl.appointed_at from department_leader dl inner join app_user u on u.id = dl.user_id inner join department d on d.id = dl.department_id
dl.department_id = #{departmentId}
order by d.id, dl.appointed_at desc, u.id

mapper.delete:
delete from department_leader
where user_id = #{userId}
  and department_id = #{departmentId}

mapper.select:
select count(1)
from department_leader
where user_id = #{userId}
